import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Switch from 'flarum/common/components/Switch';

/**
 * Otomatik koleksiyon kuralları: hedef başlık + yapay zekâya sorulacak evet/hayır sorusu + kaynak bölümler.
 * Kurallar ayar akışına (attrs.setting: framio-upload-exif.auto_collect_rules) JSON olarak yazılır, sayfanın
 * "Kaydet" düğmesiyle kaydedilir. Geçmiş gönderiler kural başına önizlemeyle taranır.
 */
export default class AutoCollectManager extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    this.scan = {}; // kural → { busy, items, picked:Set }
  }
  rules() {
    try {
      return JSON.parse(this.attrs.setting() || '[]') || [];
    } catch (e) {
      return [];
    }
  }
  save(rules) {
    this.attrs.setting(JSON.stringify(rules));
  }
  update(i, key, value) {
    const rules = this.rules();
    rules[i][key] = value;
    this.save(rules);
  }
  add() {
    const rules = this.rules();
    rules.push({
      key: Math.random().toString(36).slice(2, 12),
      name: '',
      target: '',
      question: '',
      tags: '',
      active: true
    });
    this.save(rules);
  }
  remove(i) {
    if (!confirm('Kural silinsin mi? (Daha önce eklenen mesajlar kalır.)')) return;
    const rules = this.rules();
    rules.splice(i, 1);
    this.save(rules);
  }
  call(body) {
    return app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/framio-media/auto-collect',
      body
    });
  }
  runScan(rule) {
    const st = this.scan[rule.key] = this.scan[rule.key] || {
      items: [],
      picked: new Set()
    };
    st.busy = true;
    st.error = '';
    this.call({
      rule: rule.key,
      action: 'scan',
      limit: 20
    }).then(r => {
      st.items = r.items || [];
      st.scanned = true;
      st.picked = new Set(st.items.filter(x => x.answer && x.confidence !== 'low').map(x => x.post_id));
    }).catch(e => {
      st.error = e.response && e.response.error || 'Tarama yapılamadı (önce ayarları kaydedin).';
    }).finally(() => {
      st.busy = false;
      m.redraw();
    });
  }
  addPicked(rule) {
    const st = this.scan[rule.key];
    if (!st || !st.picked.size) return;
    st.busy = true;
    this.call({
      rule: rule.key,
      action: 'add',
      posts: Array.from(st.picked)
    }).then(r => {
      app.alerts.show({
        type: 'success'
      }, r.added + ' gönderi başlığa eklendi.');
      st.items = st.items.filter(x => !st.picked.has(x.post_id));
      st.picked = new Set();
    }).finally(() => {
      st.busy = false;
      m.redraw();
    });
  }
  view() {
    const rules = this.rules();
    const base = app.forum.attribute('baseUrl');
    return m("div", {
      className: "FramioAuto"
    }, rules.map((r, i) => {
      const st = this.scan[r.key];
      return m("div", {
        className: "FramioAuto-rule"
      }, m("div", {
        className: "FramioAuto-row"
      }, m("input", {
        className: "FormControl",
        placeholder: "Kural ad\u0131 (\xF6r. Renkli otob\xFCsler)",
        value: r.name,
        oninput: e => this.update(i, 'name', e.target.value)
      }), m("input", {
        className: "FormControl",
        placeholder: "Hedef ba\u015Fl\u0131k adresi ya da numaras\u0131 (\xF6r. /d/245)",
        value: r.target,
        oninput: e => this.update(i, 'target', e.target.value)
      }), m(Switch, {
        state: r.active !== false,
        onchange: v => this.update(i, 'active', v)
      }, "Etkin"), m(Button, {
        className: "Button Button--icon",
        icon: "fas fa-trash",
        title: "Kural\u0131 sil",
        onclick: () => this.remove(i)
      })), m("textarea", {
        className: "FormControl",
        rows: "2",
        placeholder: "Yapay zek\xE2ya sorulacak evet/hay\u0131r sorusu (\xF6r. Arac\u0131n g\xF6vdesi a\u011F\u0131rl\u0131kl\u0131 olarak beyaz DI\u015EINDA bir renkte mi? Firma logolar\u0131 ve yaz\u0131lar say\u0131lmaz.)",
        value: r.question,
        oninput: e => this.update(i, 'question', e.target.value)
      }), m("input", {
        className: "FormControl",
        placeholder: "Hangi b\xF6l\xFCmlerden al\u0131ns\u0131n? (etiket k\u0131sa adlar\u0131, virg\xFClle; bo\u015F: t\xFCm forum)",
        value: r.tags,
        oninput: e => this.update(i, 'tags', e.target.value)
      }), m("div", {
        className: "FramioAuto-row"
      }, m(Button, {
        className: "Button",
        icon: "fas fa-search",
        loading: st && st.busy,
        onclick: () => this.runScan(r)
      }, "Ge\xE7mi\u015Fi tara (20 g\xF6nderi)"), st && st.items.length ? m(Button, {
        className: "Button Button--primary",
        icon: "fas fa-plus",
        loading: st.busy,
        onclick: () => this.addPicked(r)
      }, "Se\xE7ilenleri ekle (", st.picked.size, ")") : null, m("span", {
        className: "helpText"
      }, "Yeni g\xF6nderiler 10 dakikada bir kendili\u011Finden sorulur.")), st && st.error ? m("div", {
        className: "Alert Alert--error"
      }, st.error) : null, st && st.items.length ? m("div", {
        className: "FramioAuto-grid"
      }, st.items.map(x => m("label", {
        className: 'FramioAuto-item' + (x.answer ? ' is-yes' : ''),
        title: x.error || ''
      }, x.image ? m("img", {
        src: x.image,
        loading: "lazy",
        alt: ""
      }) : m("span", {
        className: "FramioAuto-noimg"
      }, "g\xF6rsel yok"), m("span", {
        className: "FramioAuto-meta"
      }, m("input", {
        type: "checkbox",
        checked: st.picked.has(x.post_id),
        onchange: e => {
          e.target.checked ? st.picked.add(x.post_id) : st.picked.delete(x.post_id);
        }
      }), x.answer ? ' Evet' : ' Hayır', " \xB7 ", x.confidence, m("a", {
        href: base + '/d/' + x.discussion_id + '/' + x.number,
        target: "_blank",
        rel: "noopener"
      }, " #", x.post_id))))) : st && !st.busy && st.items && !st.error && st.scanned ? m("div", {
        className: "helpText"
      }, "Sorulmam\u0131\u015F g\xF6nderi kalmad\u0131.") : null);
    }), m(Button, {
      className: "Button",
      icon: "fas fa-plus",
      onclick: () => this.add()
    }, "Kural ekle"));
  }
}
flarum.reg.add('framio-upload-exif', 'admin/components/AutoCollectManager', AutoCollectManager);